   432  static GFINLINE void latm_dmx_update_cts(GF_LATMDmxCtx *ctx)
   433  {
   434          assert(ctx->dts_inc);
   435
   436          if (ctx->timescale) {
   437                  u64 inc = ctx->dts_inc;
   438                  inc *= ctx->timescale;
   439                  inc /= GF_M4ASampleRates[ctx->sr_idx];
   440                  ctx->cts += inc;
   441          } else {
   442                  ctx->cts += ctx->dts_inc;
   443          }
   444  }
